\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Let $B$ be a separable unital $C^*$-algebra without characters and with separating tracial states. Does $B\otimes_{\min}B\otimes_{\min}\cdots$ contain a subhomogeneous $C^*$-algebra without characters?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2012/52}{[S2]}.

\subsection{Short English statement}
Let $B$ be a separable unital $C^*$-algebra without characters and with separating tracial states. Does $B\otimes_{\min}B\otimes_{\min}\cdots$ contain a subhomogeneous $C^*$-algebra without characters?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30002229 (OWR-12175-024). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2012/52}.
\end{itemize}
\label{end:30002229}

